import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { 
  FaArrowLeft, 
  FaShoppingCart, 
  FaStar, 
  FaHeart,
  FaSearch,
  FaFilter,
  FaReceipt,
  FaMapMarkerAlt,
  FaCreditCard
} from 'react-icons/fa';
import { addOrder, loadAppData } from '../data/store';
import './TribalProducts.css';

const categories = ['All', 'Textiles', 'Handicrafts', 'Food & Beverages', 'Art & Paintings', 'Wellness'];

function TribalProducts() {
  const navigate = useNavigate();
  const [products, setProducts] = useState(() => loadAppData().products);
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [searchTerm, setSearchTerm] = useState('');
  const [cart, setCart] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [address, setAddress] = useState('');
  const [paymentMethod, setPaymentMethod] = useState('UPI');
  const [bill, setBill] = useState(null);

  useEffect(() => {
    const syncProducts = () => setProducts(loadAppData().products);
    syncProducts();
    window.addEventListener('storage', syncProducts);
    return () => window.removeEventListener('storage', syncProducts);
  }, []);

  const filteredProducts = products.filter(product => {
    const matchesCategory = selectedCategory === 'All' || product.category === selectedCategory;
    const matchesSearch = product.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         product.tribe.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const cartTotal = useMemo(
    () => cart.reduce((sum, item) => sum + item.product.price * item.quantity, 0),
    [cart]
  );

  const addToCart = (product) => {
    setCart((current) => {
      const existing = current.find((item) => item.product.id === product.id);
      if (existing) {
        return current.map((item) =>
          item.product.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...current, { product, quantity: 1 }];
    });
  };

  const updateQuantity = (productId, change) => {
    setCart((current) =>
      current
        .map((item) =>
          item.product.id === productId
            ? { ...item, quantity: Math.max(0, item.quantity + change) }
            : item
        )
        .filter((item) => item.quantity > 0)
    );
  };

  const toggleFavorite = (productId) => {
    setFavorites(prev => 
      prev.includes(productId) 
        ? prev.filter(id => id !== productId)
        : [...prev, productId]
    );
  };

  const discount = (price, mrp) => Math.round(((mrp - price) / mrp) * 100);

  const handleCheckout = () => {
    if (!cart.length) {
      alert('Please add at least one product to the cart.');
      return;
    }

    if (!address.trim()) {
      alert('Please enter your delivery address before placing the order.');
      return;
    }

    const order = addOrder({
      userEmail: 'user@example.com',
      items: cart.map(({ product, quantity }) => ({
        name: product.name,
        quantity,
        price: product.price
      })),
      address,
      paymentMethod,
      total: cartTotal
    });

    setBill(order);
    setCart([]);
    setAddress('');
  };

  return (
    <div className="tribal-products-container">
      <motion.header
        className="products-header"
        initial={{ y: -50 }}
        animate={{ y: 0 }}
      >
        <button className="back-btn" onClick={() => navigate('/')}>
          <FaArrowLeft /> Back
        </button>
        <h1>🛍️ Tribal Products Store</h1>
        <div className="cart-button">
          <FaShoppingCart size={24} />
          {cart.length > 0 && <span className="cart-badge">{cart.length}</span>}
        </div>
      </motion.header>

      <main className="products-main">
        <motion.div
          className="store-banner"
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
        >
          <h2>🌿 Authentic Tribal Products</h2>
          <p>Support indigenous artisans • Handcrafted with love • Direct from Nilgiris</p>
        </motion.div>

        <div className="products-controls">
          <div className="search-box">
            <FaSearch />
            <input
              type="text"
              placeholder="Search products or tribes..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="category-filter">
            <FaFilter />
            <select
              value={selectedCategory}
              onChange={(e) => setSelectedCategory(e.target.value)}
            >
              {categories.map(category => (
                <option key={category} value={category}>{category}</option>
              ))}
            </select>
          </div>
        </div>

        <div className="products-grid">
          {filteredProducts.map((product, index) => (
            <motion.div
              key={product.id}
              className="product-card"
              initial={{ opacity: 0, y: 30 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.05 }}
              whileHover={{ y: -10 }}
            >
              <div className="product-image-wrapper">
                <img src={product.image} alt={product.name} className="product-image" />
                <div className="discount-badge">{discount(product.price, product.mrp)}% OFF</div>
                <button
                  className={`favorite-btn ${favorites.includes(product.id) ? 'active' : ''}`}
                  onClick={() => toggleFavorite(product.id)}
                >
                  <FaHeart />
                </button>
              </div>

              <div className="product-content">
                <span className="product-tribe">Made by {product.tribe} Tribe</span>
                <h3 className="product-name">{product.name}</h3>
                <p className="product-description">{product.description}</p>

                <div className="product-rating">
                  <span className="rating-badge"><FaStar /> {product.rating}</span>
                  <span className="reviews">({product.reviews} reviews)</span>
                </div>

                <div className="product-price">
                  <span className="current-price">₹{product.price.toLocaleString()}</span>
                  <span className="mrp">MRP ₹{product.mrp.toLocaleString()}</span>
                </div>

                <div className="stock-status">✓ In Stock</div>

                <button
                  className="add-cart-btn"
                  onClick={() => addToCart(product)}
                >
                  <FaShoppingCart /> Add to Cart
                </button>
              </div>
            </motion.div>
          ))}
        </div>

        {filteredProducts.length === 0 && (
          <div className="no-products">
            <p>No products found. Try a different search or category.</p>
          </div>
        )}

        {cart.length > 0 && (
          <div className="checkout-panel">
            <h3>Checkout & Payment</h3>
            <div className="cart-list">
              {cart.map(({ product, quantity }) => (
                <div key={product.id} className="cart-item">
                  <div>
                    <strong>{product.name}</strong>
                    <p>₹{product.price} each</p>
                  </div>
                  <div className="quantity-box">
                    <button onClick={() => updateQuantity(product.id, -1)}>-</button>
                    <span>{quantity}</span>
                    <button onClick={() => updateQuantity(product.id, 1)}>+</button>
                  </div>
                </div>
              ))}
            </div>

            <div className="checkout-form">
              <label>
                Delivery Address
                <textarea
                  rows="3"
                  value={address}
                  onChange={(e) => setAddress(e.target.value)}
                  placeholder="Enter full delivery address, landmark, and city"
                />
              </label>

              <label>
                Payment Method
                <select value={paymentMethod} onChange={(e) => setPaymentMethod(e.target.value)}>
                  <option value="UPI">UPI / GPay / PhonePe</option>
                  <option value="Card">Debit / Credit Card</option>
                  <option value="Cash">Cash on Delivery</option>
                </select>
              </label>
            </div>

            <div className="checkout-total">
              <span>Total</span>
              <strong>₹{cartTotal.toLocaleString()}</strong>
            </div>

            <button className="pay-button" onClick={handleCheckout}>
              <FaCreditCard /> Proceed to Pay
            </button>
          </div>
        )}

        {bill && (
          <div className="bill-card">
            <div className="bill-header">
              <FaReceipt size={28} />
              <h3>Payment Receipt</h3>
            </div>
            <p><strong>Bill No:</strong> {bill.billNumber}</p>
            <p><strong>Payment Method:</strong> {bill.paymentMethod}</p>
            <p><strong>Delivery Address:</strong> {bill.address}</p>
            <div className="bill-items">
              {bill.items.map((item) => (
                <div key={`${bill.billNumber}-${item.name}`} className="bill-item">
                  <span>{item.name} × {item.quantity}</span>
                  <span>₹{(item.price * item.quantity).toLocaleString()}</span>
                </div>
              ))}
            </div>
            <div className="bill-total">
              <span>Total Paid</span>
              <strong>₹{bill.total.toLocaleString()}</strong>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

export default TribalProducts;
